const userSecretsForPersona = `-- name: UserSecretsForPersona :many
SELECT s.id, s.workspace_id, s.user_id, s.name, s.handle, s.placement, s.placement_key, s.allowed_hosts, s.read_policy, s.write_policy, s.nonce, s.ciphertext, s.expires_at, s.last_used_at, s.revision, s.created_at, s.updated_at FROM user_secrets s JOIN user_secret_personas sp ON sp.secret_id = s.id
WHERE s.workspace_id = $1 AND s.user_id = $2 AND sp.persona_id = $3
  AND ($4::uuid[] IS NULL OR s.id = ANY($4::uuid[]))
ORDER BY s.handle
`

type UserSecretsForPersonaParams struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
	PersonaID   uuid.UUID
	AllowedIds  []uuid.UUID
}

// What this persona may use; a chat's list, when it has one, narrows it.
func (q *Queries) UserSecretsForPersona(ctx context.Context, arg UserSecretsForPersonaParams) ([]UserSecret, error) {
	rows, err := q.db.Query(ctx, userSecretsForPersona,
		arg.WorkspaceID,
		arg.UserID,
		arg.PersonaID,
		arg.AllowedIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UserSecret{}
	for rows.Next() {
		var i UserSecret
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.UserID,
			&i.Name,
			&i.Handle,
			&i.Placement,
			&i.PlacementKey,
			&i.AllowedHosts,
			&i.ReadPolicy,
			&i.WritePolicy,
			&i.Nonce,
			&i.Ciphertext,
			&i.ExpiresAt,
			&i.LastUsedAt,
			&i.Revision,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
